/* Public game-to-Vault bridge only. Spark owns requested guides and feedback. */
(function(){'use strict';function path(){return ('/'+location.pathname.replace(/^\/+|\/+$/g,'')+'/').replace(/\/\//g,'/');}function family(p){return /^\/(games\/[^/]+|call-of-doodie|franchise-architect|gridiron-gm)\//.test(p)?'game':'general';}function mountBridge(){if(family(path())!=='game'||document.querySelector('[data-vault-bridge]'))return;var main=document.querySelector('main');if(!main)return;var source=path().split('/').filter(Boolean).pop();var section=document.createElement('section');section.className='vs-vault-bridge container';section.dataset.vaultBridge=source;var h=document.createElement('h2');h.textContent='Carry this world into the Vault.';var p=document.createElement('p');p.textContent='Follow the studio or inspect its public evidence before choosing your next step.';var a=document.createElement('a');a.className='button';a.href='/membership/?from='+encodeURIComponent(source);a.textContent='See the Vault path';var proof=document.createElement('a');proof.className='button button-secondary';proof.href='/proof/?from='+encodeURIComponent(source);proof.textContent='Verify the work';section.append(h,p,a,proof);main.append(section);}window.VSJourneyConductor={path:path,family:family,signal:function(){},previewFeedback:function(){if(window.VSSpark)window.VSSpark.open();}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mountBridge,{once:true});else mountBridge();})();
